// Box2 patcher: catalog facet extras (condition + exterior-colour counts, price histogram, server-side keyword exclude) as ANCHORED edits to the box's own
// deals-api files. Code only until Paul types GO. Never restarts anything, never sets a flag, never touches the database.
// Generated by scripts/box/gen-facet-extras-patch.mjs from scripts/box/facet-extras-edits.json and scrapers/lightsail-crawler/src/facetExtras.js; do not edit by hand.
//
//   node 2026-10-26-facet-extras.mjs [--dir=/opt/trimscout-deals/src] [--apply]
//
// What it changes, and nothing else:
//   deals_api_server.js      FACET_COND_PRICE const (default OFF); tables + meta columns only when on; one extra per-make aggregate in the facet rebuild only when on and
//                            within FACET_EXTRA_BUDGET_PCT (max 10); catalog payload gains exteriorColorCounts/interiorColorCounts (always, free) and, when on,
//                            conditionCounts + priceHistogram; the colour read becomes SUM(vehicle_count) GROUP BY colour; list calls echo excludeApplied; status reports extras
//   inventoryListQuery.js    exclude= keyword filter (only with a make) and excludeTerms in the result
//   facetExtras.js           NEW module next to the others
// Prerequisite: the options-paid-only patch (2026-10-19-options-paid-only.mjs) is installed; this refuses to run otherwise.
//
// Without --apply it is a DRY RUN: it reads the files, checks every anchor (each "find" must occur EXACTLY once, or the edit's marker must already be there),
// stages the patched modules in a temp dir, loads them and runs smoke checks (flag defaults OFF; no-exclude queries are unchanged; the budget holds), and writes
// nothing to --dir. With --apply it
//   1. writes patched copies to <file>.new.mjs and node --check's them,
//   2. copies each original to <file>.bak.<timestamp> (cp -p), moves the new file into place (same mode), and installs facetExtras.js.
// Takes effect at the next deals-api restart (idle window, Paul's call). FACET_COND_PRICE stays OFF until someone sets it in the process env.
//
// RESTORE: for each backup the apply printed: cp -p <file>.bak.<STAMP> <file>   (files: deals_api_server.js inventoryListQuery.js); then rm facetExtras.js;
//   then restart only if deals-api was already restarted onto the new code. All at once:
//   cd <dir> && for f in deals_api_server inventoryListQuery; do cp -p $f.js.bak.<STAMP> $f.js; done; rm -f facetExtras.js
//   (The inv_price_facets / inv_price_summary tables and the two inv_facet_meta columns are additive and harmless to leave; DROP them only if asked.)
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { execFileSync } from "node:child_process";
import { pathToFileURL } from "node:url";

const args = Object.fromEntries(process.argv.slice(2).map((a) => { const [k, ...v] = a.replace(/^--/, "").split("="); return [k, v.length ? v.join("=") : true]; }));
const DIR = path.resolve(args.dir || "/opt/trimscout-deals/src");
const APPLY = Boolean(args.apply);
const STAMP = new Date().toISOString().replace(/[-:T]/g, "").slice(0, 14);
const count = (hay, needle) => { let n = 0, i = 0; while ((i = hay.indexOf(needle, i)) >= 0) { n++; i += needle.length; } return n; };

const EDITS = /*EDITS*/null;
for (const e of EDITS) if (e.find.includes(e.marker) || !e.replace.includes(e.marker)) throw new Error(`edit ${e.id}: marker must be in the replacement and not in the anchor`);

const NEW_MODULE = "facetExtras.js";
const MODULE_TEXT = /*MODULE_TEXT*/null;

// ---- prerequisites on the box ----
for (const f of [...new Set(EDITS.map((e) => e.file))]) if (!fs.existsSync(path.join(DIR, f))) { console.error(`ABORT: ${path.join(DIR, f)} is missing - is --dir the box's src directory? Nothing written.`); process.exit(2); }
if (!fs.existsSync(path.join(DIR, "optionsPaidOnlyServer.js"))) { console.error("ABORT: optionsPaidOnlyServer.js is missing - apply 2026-10-19-options-paid-only.mjs first. Nothing written."); process.exit(2); }

const files = [...new Set(EDITS.map((e) => e.file))];
const plan = [];
let abort = false;
for (const f of files) {
  const p = path.join(DIR, f);
  const original = fs.readFileSync(p, "utf8");
  let text = original;
  for (const e of EDITS.filter((x) => x.file === f)) {
    const nFind = count(text, e.find), nMark = count(text, e.marker);
    let status;
    if (nMark >= 1) status = nMark === 1 ? "already applied" : `MARKER PROBLEM: marker occurs ${nMark}x`;
    else if (nFind === 1) { text = text.replace(e.find, () => e.replace); status = "will apply"; }
    else status = `ANCHOR PROBLEM: find occurs ${nFind}x, marker ${nMark}x`;
    if (/PROBLEM/.test(status)) abort = true;
    console.log(`${f} :: ${e.id} :: ${status}`);
  }
  plan.push({ f, p, original, text });
}
if (abort) { console.error("ABORT: nothing written. (The box's file differs from the repo's at that anchor: send me the lines around it.)"); process.exit(2); }

// Stage the patched modules in a temp dir and exercise them.
const stage = fs.mkdtempSync(path.join(os.tmpdir(), "facetextras-stage-"));
const verify = async () => {
  fs.writeFileSync(path.join(stage, "package.json"), JSON.stringify({ type: "module" }));
  for (const f of fs.readdirSync(DIR)) if (/\.(js|json)$/.test(f) && f !== "package.json") fs.copyFileSync(path.join(DIR, f), path.join(stage, f));
  for (const x of plan) fs.writeFileSync(path.join(stage, x.f), x.text);
  fs.writeFileSync(path.join(stage, NEW_MODULE), MODULE_TEXT);
  execFileSync(process.execPath, ["--check", path.join(stage, "deals_api_server.js")], { stdio: "pipe" });
  const imp = (f) => import(pathToFileURL(path.join(stage, f)).href);
  const fx = await imp(NEW_MODULE), lq = await imp("inventoryListQuery.js");
  const server = plan.find((x) => x.f === "deals_api_server.js").text;

  // 1. the flag defaults to OFF and is read only through facetExtrasEnabled()
  if (fx.facetExtrasEnabled({}) !== false) throw new Error("facetExtrasEnabled({}) is not false");
  for (const v of ["", "0", "off", "false"]) if (fx.facetExtrasEnabled({ FACET_COND_PRICE: v })) throw new Error(`flag read as ON for "${v}"`);
  if (!/const FACET_EXTRAS = facetExtrasEnabled\(\);/.test(server)) throw new Error("deals_api_server.js does not read the flag through facetExtrasEnabled()");
  if (/FACET_COND_PRICE\s*[=:]\s*["']?(1|true|on)/i.test(server)) throw new Error("the patched server hard-codes the flag on");
  if (process.env.FACET_COND_PRICE) console.log(`NOTE: FACET_COND_PRICE=${process.env.FACET_COND_PRICE} is set in THIS shell; the server reads its own pm2 environment, not this one.`);
  // 2. a list query without exclude= is unchanged; with it and a make, the predicate is there; without a make it is ignored
  const q = (pairs) => lq.inventoryListQuery(new URLSearchParams(pairs));
  const plain = q([["make", "Toyota"], ["inStock", "1"]]);
  if (/CONCAT_WS|NOT \(/.test(plain.sql + plain.countSql) || plain.excludeTerms.length) throw new Error("a query without exclude= changed");
  const ex = q([["make", "Toyota"], ["inStock", "1"], ["exclude", "Black"]]);
  if (!/NOT \(CONCAT_WS/.test(ex.countSql) || ex.args[ex.args.length - 1] !== "%black%") throw new Error("exclude predicate missing or wrong");
  if (q([["state", "NJ"], ["inStock", "1"], ["exclude", "black"]]).excludeTerms.length) throw new Error("exclude honoured without a make");
  // 3. the budget: an expensive extra query is cut off at about 10% of the rest of the build
  let el = 0, em = 0;
  for (let i = 0; i < 60; i++) { if (fx.budgetAllows({ makesDone: i, elapsedMs: el, extraMs: em, budgetPct: 10 })) { el += 1000; em += 1000; } el += 1000; }
  if (100 * em / (el - em) > 10 + 1000 / 60) throw new Error("budget simulation exceeded 10%");
  // 4. folding
  const f = fx.foldExtras([{ cond: "new", bucket: 6, n: 2 }, { cond: "used", bucket: -1, n: 1 }]);
  if (f.conditionCounts.new !== 2 || f.conditionCounts.used !== 1 || f.priceHistogram.all[6] !== 2) throw new Error("foldExtras result wrong");
  console.log("staged modules load; flag defaults OFF; queries without exclude= unchanged; exclude predicate present only with a make; budget holds");
};
try { await verify(); } catch (err) { console.error(`ABORT (nothing written to ${DIR}): ${err.message}`); fs.rmSync(stage, { recursive: true, force: true }); process.exit(3); }
fs.rmSync(stage, { recursive: true, force: true });
if (!APPLY) { console.log("DRY RUN ok - nothing written. Re-run with --apply."); process.exit(0); }

const staged = [];
try {
  for (const x of plan) {
    if (x.text === x.original) { console.log(`${x.f}: nothing to change`); continue; }
    const newPath = path.join(DIR, x.f.replace(/\.js$/, ".new.mjs"));
    staged.push({ ...x, newPath });
    fs.writeFileSync(newPath, x.text);
    execFileSync(process.execPath, ["--check", newPath], { stdio: "pipe" });
  }
} catch (err) {
  for (const x of staged) fs.rmSync(x.newPath, { force: true });
  console.error(`ABORT (originals untouched, temp files removed): ${err.message}`);
  process.exit(3);
}
for (const x of staged) {
  const bak = `${x.p}.bak.${STAMP}`;
  fs.copyFileSync(x.p, bak); fs.chmodSync(bak, fs.statSync(x.p).mode);
  fs.chmodSync(x.newPath, fs.statSync(x.p).mode);
  fs.renameSync(x.newPath, x.p);
  console.log(`${x.f}: backup ${bak}; patched file in place. Rollback: cp -p ${bak} ${x.p}`);
}
const mp = path.join(DIR, NEW_MODULE);
if (fs.existsSync(mp) && fs.readFileSync(mp, "utf8") === MODULE_TEXT) console.log(`${NEW_MODULE}: already installed, unchanged.`);
else {
  if (fs.existsSync(mp)) { fs.copyFileSync(mp, `${mp}.bak.${STAMP}`); console.log(`${NEW_MODULE}: existing file backed up to ${mp}.bak.${STAMP}`); }
  fs.writeFileSync(mp + ".new", MODULE_TEXT); fs.chmodSync(mp + ".new", 0o664); fs.renameSync(mp + ".new", mp);
  console.log(`${NEW_MODULE}: installed (${mp}). Rollback: rm it, or restore the .bak.`);
}
console.log(`DONE (backup stamp ${STAMP}). deals-api has NOT been restarted and FACET_COND_PRICE was not set; the new code loads at the next restart with the flag still off.`);
